{
  "lemmas": [
    {
      "lemma": "property lemma_1; @(posedge clk) disable iff (rst) ((n != '0) |-> (m < n)); endproperty",
      "explanation": "After reset, m is zero, so the relation holds for nonzero n. Between resets n is unchanged, and m can only be assigned x when x < n; otherwise m retains its value."
    },
    {
      "lemma": "property lemma_2; @(posedge clk) disable iff (rst) ((state == DONE) |-> (n != '0)); endproperty",
      "explanation": "Reset enters LOOP. The only transition into DONE requires n > 0, and n remains unchanged until reset. Thus DONE implies the condition needed to apply lemma_1."
    }
  ]
}
